// One row per poll for a single device (SD-GEN072).
// No uptime/downtime here - that gets calculated in Looker Studio from
// is_online across polled_ts.

// Change this (or add more names to the array) to widen the scope.
const TARGET_NAMES = ['SD-GEN072'];

const wanted = new Set(TARGET_NAMES.map((n) => n.trim().toUpperCase()));
const matches = (d) => wanted.has(String(d.name || '').trim().toUpperCase());

const now = new Date();
const nowIso = now.toISOString();

const num = (v) =>
  v === null || v === undefined || v === '' || v === 'N/A' ? null : Number(v);

const ts = (s) => {
  const t = new Date(String(s || '').replace(' ', 'T') + 'Z');
  return Number.isNaN(t.getTime()) ? null : t;
};

const rows = $input.all().filter(({ json: d }) => matches(d));

// Loud failure beats a silently empty table: if the name ever changes in RMS
// this throws instead of quietly writing nothing for weeks.
if (rows.length === 0) {
  throw new Error(
    `No device matched ${TARGET_NAMES.join(', ')} in the RMS response ` +
    `(${$input.all().length} devices returned). Check the device name in RMS.`
  );
}

return rows.map(({ json: d }) => {
  const devTs = ts(d.last_update_at);
  // 1 = online, 0 = offline, anything else = unknown (kept as null so a
  // bad poll doesn't get counted as downtime in the report).
  const online = d.status === 1 ? true : d.status === 0 ? false : null;

  return {
    json: {
      device_id: d.id,
      polled_ts: nowIso,                          // the run timestamp
      device_ts: devTs ? devTs.toISOString() : null, // RMS data freshness
      is_online: online,

      name: d.name || null,
      serial: d.serial || null,
      imei: d.imei || null,
      model: d.model || null,
      firmware: d.firmware || null,
      company_id: d.company_id ?? null,

      rssi_dbm: num(d.signal),
      rsrp_dbm: num(d.rsrp),
      rsrq_db: num(d.rsrq),
      sinr_db: num(d.sinr),
      rscp_dbm: num(d.rscp),
      ecio_db: num(d.ecio),

      conn_type: d.connection_type || null,
      conn_state: d.connection_state || null,
      operator: d.operator || null,
      network_state: d.network_state || null,
      wan_state: d.wan_state || null,
      cell_id: d.cell_id || null,
      tac: d.tac === 'N/A' ? null : d.tac || null,
      temp_c: num(d.temperature),
      sent_bytes: num(d.sent),
      received_bytes: num(d.received),

      monitoring_enabled: d.monitoring_enabled ?? null,
    },
  };
});
